clc; clearvars;
%%
%[text] Settings
dataFolder = fullfile('data', '20260427');
processingFolder = fullfile('..', '..', 'O3_Lidar', 'proc_functions');
addpath(genpath(processingFolder));

channels = [1 2 3 4];
channelLabels = ["287 far", "299 far", "287 near", "299 near"];
backgroundRange_km = [12 24];
frequencyBand_MHz = [0.05 19.5];
exampleChannel = 1;                   % Index into channels
exampleProfiles = [7 14 20 24];
plotRange_km = [15 16];
%[text] Read and scale signals \[range bin, profile, channel\].
[analog_raw, photon_counts, times, configs] = read_lidar_datafiles(dataFolder, "bin", "ol");
analog_raw = analog_raw(:,:,channels);
photon_counts = photon_counts(:,:,channels);

[nBins, nProfiles, nChannels] = size(photon_counts);

binWidth_m = configs(1).binwidth(channels(1));
binDuration_s = 2 * binWidth_m / physconst("LightSpeed");
range_km = (1:nBins)' * binWidth_m / 1000;

pc_MHz = zeros(size(photon_counts));
an_mV = zeros(size(analog_raw));
inputRanges_mV = [500 100 20];

for profile = 1:nProfiles
    for channel = 1:nChannels
        prof_id = channels(channel);

        assert(configs(profile).binwidth(prof_id) == binWidth_m && configs(profile).bins(prof_id) == nBins, 'Range grids must match.');
        shots = configs(profile).shots(prof_id);
        fullScale_mV = inputRanges_mV(configs(profile).range(prof_id) + 1);
        adcScale = 2^configs(profile).adcbits(prof_id) - 1;

        pc_MHz(:,profile,channel) = photon_counts(:,profile,channel) / shots / binDuration_s / 1e6;
        an_mV(:,profile,channel) = analog_raw(:,profile,channel) * fullScale_mV / adcScale / shots;
    end
end
%%
backgroundBins = range_km >= backgroundRange_km(1) & range_km <= backgroundRange_km(2);

bg_mV = mean(an_mV(backgroundBins,:,:),1);
bg_MHz = mean(pc_MHz(backgroundBins,:,:),1);

an_mV_bgc = an_mV - bg_mV;
pc_MHz_bgc = pc_MHz - bg_MHz;

scaled_variance = NaN(nProfiles,nChannels);

for channel = 1:nChannels
    for profile = 1:nProfiles

        counts = photon_counts(backgroundBins,profile,channel);
        residual = detrend(counts);
        if mean(counts) > 0
            scaled_variance(profile,channel) = var(residual,1) / mean(counts);
        end

    end
end
%%
%[text] Plots
%[text] Profiles
prof_id = 3; %[control:slider:6345]{"position":[11,12]}
%%
tiledlayout(2,1); %[output:3b7f4b78]
nexttile %[output:3b7f4b78]
plot(range_km,squeeze(an_mV(:,prof_id,:))) %[output:3b7f4b78]
xlim(plotRange_km) %[output:3b7f4b78]
nexttile %[output:3b7f4b78]
plot(range_km,squeeze(pc_MHz(:,prof_id,:))) %[output:3b7f4b78]
xlim(plotRange_km) %[output:3b7f4b78]
%%
figure; %[output:2b02e8de]
plot(range_km,an_mV_bgc(:,prof_id,1),'DisplayName','287 FR') %[output:2b02e8de]
hold on %[output:2b02e8de]
plot(range_km,an_mV_bgc(:,prof_id,2),'DisplayName','299 FR') %[output:2b02e8de]
hold off %[output:2b02e8de]

yscale log  %[output:2b02e8de]
grid on %[output:2b02e8de]
legend %[output:2b02e8de]
figure %[output:5cccf5db]
plot(range_km,pc_MHz_bgc(:,prof_id,1),'DisplayName','287 FR') %[output:5cccf5db]
hold on %[output:5cccf5db]
plot(range_km,pc_MHz_bgc(:,prof_id,2),'DisplayName','299 FR') %[output:5cccf5db]
hold off %[output:5cccf5db]

yscale log  %[output:5cccf5db]
grid on %[output:5cccf5db]
legend %[output:5cccf5db]
%%
%[text] Background values
figure; %[output:58b36808] %[output:40700603] %[output:8d2e40d7] %[output:280eec0f]
plot(squeeze(bg_MHz)) %[output:280eec0f]
xlabel("Profile") %[output:280eec0f]
ylabel("MHz") %[output:280eec0f]
legend(["287 FR" "299 FR" "287 NR" "299 NR"]) %[output:280eec0f]
grid on %[output:280eec0f]
figure; %[output:05e94874]
plot(squeeze(bg_mV)) %[output:05e94874]
grid on %[output:05e94874]
xlabel("Profile") %[output:05e94874]
ylabel("mV") %[output:05e94874]
legend(["287 FR" "299 FR" "287 NR" "299 NR"]) %[output:05e94874]
grid on %[output:05e94874]
%%
%[text] Spectrum
spectrogram(an_mV(:,1,1),'yaxis') %[output:91f37821] %[output:9a7916f1]
spectrogram(pc_MHz(:,1,1),'yaxis') %[output:46d7b3f0]

